        getLogger().info("- MenuGUI & MenuListener registered");

        // NPC listener（BeautyQuests 就緒後 factory 才不為 null，但 listener 可以先注冊）
        org.bukkit.Bukkit.getScheduler().runTask(this, () -> {
            if (beautyQuestsHook.getNpcFactory() != null) {
