                        new com.customrpg.integration.npc.NpcListener(npcManager, beautyQuestsHook.getNpcFactory()), this);
                getLogger().info("- NpcListener registered");
            } else {
                getLogger().info("- NpcListener skipped (BeautyQuests not enabled)");
            }
        });
    }

